# ============================================================================= # SpotifyDL v2 — Windows PowerShell Setup Script (One-Time) # # Usage: #   $env:GITHUB_TOKEN = 'ghp_xxxxxxxx' #   .scripts/setup-github.ps1 # ============================================================================= param( [string]$GithubUser = '', [string]$RepoName = 'spotifydl-v2' ) # Colors $Red = 'Red' $Green = 'Green' $Blue = 'Cyan' $Yellow = 'Yellow' # Check token if (-not $env:GITHUB_TOKEN) { Write-Host 'ERROR: GITHUB_TOKEN not set!' -ForegroundColor $Red Write-Host 'Set it: $env:GITHUB_TOKEN = ghp_xxxxxxxx' -ForegroundColor $Yellow exit 1 } # Banner Write-Host '' Write-Host '╔═══════════════════════════════════════════════════════════════╗' -ForegroundColor $Blue Write-Host '║ 🎵 SpotifyDL v2 — GitHub Setup (Windows) ║' -ForegroundColor $Blue Write-Host '╚═══════════════════════════════════════════════════════════════╝' -ForegroundColor $Blue Write-Host '' # Verify token Write-Host '🔐 Verifying GitHub token...' -ForegroundColor $Blue try { $headers = @{ Authorization = 'token ' + $env:GITHUB_TOKEN } $user = Invoke-RestMethod -Uri 'https://api.github.com/user' -Headers $headers -ErrorAction Stop $GithubUser = $user.login Write-Host ('✅ Token verified for: ' + $GithubUser) -ForegroundColor $Green } catch { Write-Host ('❌ Invalid token: ' + $_.Exception.Message) -ForegroundColor $Red exit 1 } # Check git if (-not (Get-Command git -ErrorAction SilentlyContinue)) { Write-Host '❌ git not found. Install from https://git-scm.com' -ForegroundColor $Red exit 1 } # Check if in repo if (-not (Test-Path '.git')) { Write-Host '❌ Not a git repository. Run from project root.' -ForegroundColor $Red exit 1 } # Create repo via API Write-Host '' Write-Host '📦 Creating GitHub repository...' -ForegroundColor $Blue $body = @{ name = $RepoName description = 'Advanced Spotify downloader with hybrid engines' private = $false auto_init = $false } | ConvertTo-Json try { $response = Invoke-RestMethod -Uri 'https://api.github.com/user/repos' -Method Post -Headers @{ Authorization = 'token ' + $env:GITHUB_TOKEN; 'Content-Type' = 'application/json' } -Body $body Write-Host ('✅ Repository created: ' + $response.html_url) -ForegroundColor $Green } catch { if ($_.Exception.Response.StatusCode -eq 422) { Write-Host '⚠️ Repository already exists, continuing...' -ForegroundColor $Yellow } else { Write-Host ('❌ Failed: ' + $_.Exception.Message) -ForegroundColor $Red exit 1 } } # Set remote and push $remoteUrl = 'https://' + $GithubUser + ':' + $env:GITHUB_TOKEN + '@github.com/' + $GithubUser + '/' + $RepoName + '.git' $existingRemote = git remote get-url origin 2>$null if ($existingRemote) { git remote set-url origin $remoteUrl } else { git remote add origin $remoteUrl } Write-Host '' Write-Host '📤 Pushing code to GitHub...' -ForegroundColor $Blue git branch -M main 2>$null git add -A git commit -m 'Initial commit: SpotifyDL v2' -ErrorAction SilentlyContinue git push -u origin main --force Write-Host '✅ Code pushed!' -ForegroundColor $Green # Save config $configPath = '.github-config' @GITHUB_USER=$GithubUser REPO_NAME=$RepoName@ | Out-File -FilePath $configPath -Encoding UTF8 Write-Host '💾 Config saved to .github-config' -ForegroundColor $Green # Final Write-Host '' Write-Host '╔═══════════════════════════════════════════════════════════════╗' -ForegroundColor $Green Write-Host '║ ✅ SETUP COMPLETE! ║' -ForegroundColor $Green Write-Host '╚═══════════════════════════════════════════════════════════════╝' -ForegroundColor $Green Write-Host '' Write-Host ('📁 Repo: https://github.com/' + $GithubUser + '/' + $RepoName) -ForegroundColor $Green Write-Host '' Write-Host '📋 NEXT STEPS:' -ForegroundColor $Yellow Write-Host '1. Go to GitHub → Settings → Secrets → Actions' -ForegroundColor $Yellow Write-Host '2. Add: FLY_API_TOKEN (run: flyctl auth token)' -ForegroundColor $Yellow Write-Host '3. Add: RENDER_API_KEY + RENDER_SERVICE_ID' -ForegroundColor $Yellow Write-Host '4. Run: .scripts/push-and-deploy.ps1' -ForegroundColor $Yellow